class Solution {
public:
    int bitwiseComplement(int n) {
        if (n == 0) return 1;
        unsigned int mask = 1;
        while (mask < (unsigned int)n) {
            mask = (mask << 1) | 1;
        }
        return n ^ mask;
    }
};

class Solution {
    public int bitwiseComplement(int n) {
        if (n == 0) return 1;
        int mask = 1;
        while (mask < n) {
            mask = (mask << 1) | 1;
        }
        return n ^ mask;
    }
}

var bitwiseComplement = function(n) {
    if (n === 0) return 1;
    let mask = 1;
    while (mask < n) {
        mask = (mask << 1) | 1;
    }
    return n ^ mask;
};
